SELECT int32 = uint64 AS c0, toTypeName(int32 = uint64) AS t0, int32 != uint64 AS c1, toTypeName(int32 != uint64) AS t1, int32 < uint64 AS c2, toTypeName(int32 < uint64) AS t2, int32 <= uint64 AS c3, toTypeName(int32 <= uint64) AS t3, int32 > uint64 AS c4, toTypeName(int32 > uint64) AS t4, int32 >= uint64 AS c5, toTypeName(int32 >= uint64) AS t5 FROM he24.numeric ORDER BY row_id
